import{_t as e,it as t,n,ot as r,rt as i,xt as a}from"./chunks/framework.C5Z6qjff.js";var o=JSON.parse(`{"title":"Anmelden","description":"","frontmatter":{"title":"Anmelden","covers":{"screens":["SCR-001","SCR-003","SCR-004","SCR-005"],"stories":["US-001","US-005","US-006","US-010","US-011","US-021","US-023","US-024","US-025","US-026","US-027","US-029","US-030"]}},"headers":[],"relativePath":"de/usage/login.md","filePath":"de/usage/login.md"}`),s={name:`de/usage/login.md`};function c(n,o,s,c,l,u){let d=a(`Screenshot`);return e(),i(`div`,null,[o[0]||=t(`<h1 id="anmelden" tabindex="-1">Anmelden <a class="header-anchor" href="#anmelden" aria-label="Permalink to “Anmelden”">​</a></h1><p>Öffne die Weboberfläche und wähle <em>Log in</em>. Die Seite <em>Log in to OEA</em> bietet pro Identity-Provider deiner Organisation einen Button <em>Log in with …</em> und darunter die Anmeldung mit dem lokalen Systemadmin-Konto.</p><p>Die Weboberfläche ist in dieser Version nur auf Englisch verfügbar; dieses Handbuch nennt ihre Beschriftungen deshalb im englischen Original.</p><h2 id="uber-deinen-identity-provider-anmelden" tabindex="-1">Über deinen Identity-Provider anmelden <a class="header-anchor" href="#uber-deinen-identity-provider-anmelden" aria-label="Permalink to “Über deinen Identity-Provider anmelden”">​</a></h2><ol><li>Wähle <em>Log in with</em> und den Namen deines Providers.</li><li>Melde dich wie gewohnt bei deinem Provider an; er schickt dich zurück zu OEA.</li><li>Du bist angemeldet. Die Kopfzeile zeigt <em>Catalogs</em>, dein Profil und <em>Log out</em>.</li></ol><p>Deine Administration muss deine Person angelegt und an deine Identität beim Provider gebunden haben. Ist das nicht der Fall, zeigt die Anmeldeseite <em>Login failed</em> – aus Sicherheitsgründen ohne den genauen Grund; deine Administration findet ihn im Audit-Log. Ist der Provider nicht erreichbar, bittet dich die Seite, es später erneut zu versuchen.</p><p>Deine Rollen kommen aus deinen Gruppen beim Provider. Rollen mit administrativen Berechtigungen gelten nur, wenn du dich beim Provider mit einem zweiten Faktor angemeldet hast.</p><h2 id="mit-dem-lokalen-systemadmin-konto-anmelden" tabindex="-1">Mit dem lokalen Systemadmin-Konto anmelden <a class="header-anchor" href="#mit-dem-lokalen-systemadmin-konto-anmelden" aria-label="Permalink to “Mit dem lokalen Systemadmin-Konto anmelden”">​</a></h2><p>Gib Anmeldename und Passwort des Systemadmin-Kontos ein und wähle <em>Log in</em>. Nach der Setup-Phase fragt die Seite nach dem Code deiner Authenticator-App: Gib ihn ein und wähle <em>Confirm</em>. <em>Start again</em> führt zurück zum Passwortschritt.</p>`,9),r(d,{name:`login`,alt:`Anmeldeseite mit den Providern und der Anmeldung des lokalen Systemadmin-Kontos`}),o[1]||=t(`<ul><li>Nach fünf falschen Codes musst du wieder mit dem Passwort beginnen.</li><li>Nach wiederholt falschen Passwörtern werden weitere Versuche verzögert (höchstens 15 Minuten).</li><li>Jede Anmeldung und jeder fehlgeschlagene Versuch – über einen Provider oder mit dem lokalen Konto – steht mit Zeit, Mechanismus und Ergebnis im Audit-Log (<code>auth.login</code>, <code>auth.login-failed</code>); den internen Grund eines Fehlschlags nennt nur das Audit-Log.</li></ul><h2 id="mit-e-mail-adresse-und-passwort-anmelden" tabindex="-1">Mit E-Mail-Adresse und Passwort anmelden <a class="header-anchor" href="#mit-e-mail-adresse-und-passwort-anmelden" aria-label="Permalink to “Mit E-Mail-Adresse und Passwort anmelden”">​</a></h2><p>Betreibt deine Organisation OEA ohne Identity-Provider, gibt dir deine Administration ein Initialpasswort. Gib deine E-Mail-Adresse und dieses Passwort im lokalen Formular der Anmeldeseite ein.</p><ol><li>Nach der ersten Anmeldung öffnet sich die Seite <em>Change password</em>. Gib das Initialpasswort als aktuelles Passwort ein und wähle zweimal dein eigenes Passwort. Bis dahin ist nichts anderes verfügbar.</li><li>Ab dann meldest du dich mit deiner E-Mail-Adresse und deinem eigenen Passwort an. Unter <code>/me/password</code> kannst du es wieder ändern; das beendet deine anderen Sitzungen.</li></ol><ul><li>Dein Passwort muss die Passwort-Richtlinie deiner Organisation erfüllen: mindestens 12 Zeichen und eventuell eine größere Mindestlänge, bestimmte Zeichentypen oder ein Passwort, das du nicht kürzlich verwendet hast. Erfüllt es sie nicht, listet die Seite jede verfehlte Regel auf.</li><li><em>Suggest a password</em> zeigt ein erzeugtes Passwort, das die Richtlinie erfüllt. Speichere es in deinem Passwortmanager und übernimm es dann mit <em>Use as new password</em>. OEA behält den Vorschlag nicht.</li><li>Lässt deine Organisation Passwörter ablaufen, öffnet sich die Seite <em>Change password</em> bei der ersten Anmeldung nach dem Ablauf, wie nach einem Initialpasswort.</li><li>Das Initialpasswort läuft nach der Zeit ab, die deine Administration gewählt hat (Standard 72 Stunden). Ein abgelaufenes Initialpasswort scheitert wie ein falsches; bitte deine Administration um ein neues.</li><li>Hast du dein Passwort vergessen, setzt deine Administration es zurück und gibt dir ein temporäres Passwort. Dein altes Passwort und alle deine Sitzungen enden sofort; bei der nächsten Anmeldung wählst du ein neues Passwort.</li><li>Eine fehlgeschlagene Anmeldung verrät nie, ob das Konto existiert, und jeder Fehlversuch dauert gleich lang.</li><li>Rollen mit administrativen Berechtigungen brauchen einen zweiten Faktor. Sie gelten erst nach einer Anmeldung mit Passwort und Code aus deiner Authenticator-App (siehe <a href="#set-up-a-second-factor">Zweiten Faktor einrichten</a>).</li><li>Hast du eine Authenticator-App eingerichtet, fragt die Anmeldung nach dem Passwort nach ihrem Code. Ein falscher Code scheitert wie ein falsches Passwort; nach fünf falschen Codes beginnst du wieder mit dem Passwort.</li></ul><h2 id="dein-profil" tabindex="-1">Dein Profil <a class="header-anchor" href="#dein-profil" aria-label="Permalink to “Dein Profil”">​</a></h2><p><em>Profile</em> (<code>/me</code>) zeigt deinen Namen, die Kontoart, ob deine Sitzung mit einem zweiten Faktor bestätigt ist, und deine Rollen. Ist dir noch keine Rolle zugewiesen, sagt dir das Profil das; bitte deine Administration um Zugriff.</p><h2 id="set-up-a-second-factor" tabindex="-1">Zweiten Faktor einrichten <a class="header-anchor" href="#set-up-a-second-factor" aria-label="Permalink to “Zweiten Faktor einrichten”">​</a></h2><p>Ein zweiter Faktor ist eine Authenticator-App (jede App für zeitbasierte Einmalpasswörter, TOTP) auf deinem Telefon. Das lokale Systemadmin-Konto braucht einen, um die Setup-Phase zu beenden (siehe <a href="./../setup/first-administrator">Erster Administrator</a>). Meldest du dich mit E-Mail-Adresse und Passwort an, bietet OEA ihn nach der Anmeldung an, solange du keinen hast; mit <em>Skip for now</em> richtest du ihn später ein.</p><ol><li>Wähle in <em>Profile</em> den Button <em>Set up a second factor</em> (oder <em>Add an authenticator app</em>). Gib ihr bei Bedarf einen Namen, zum Beispiel das Gerät; ohne Namen heißt sie „Authenticator app“ mit dem Datum.</li><li>Wähle <em>Set up authenticator app</em> und scanne den QR-Code mit der App.</li><li>Gib den Code aus der App unter <em>Code from the app</em> ein und wähle <em>Confirm</em>.</li></ol>`,10),r(d,{name:`second-factor-enroll`,alt:`Einrichten der Authenticator-App mit QR-Code und Codefeld`}),o[2]||=t(`<p>Die Seite bestätigt, dass die Authenticator-App eingerichtet und die Sitzung bestätigt ist. Das Einrichten eines zweiten Faktors braucht eine Anmeldung innerhalb der letzten 5 Minuten; sonst bittet dich die Seite, dich erneut anzumelden.</p><ul><li>Du kannst mehrere Authenticator-Apps einrichten, zum Beispiel eine auf einem Ersatztelefon. Bei der Anmeldung funktioniert ein Code jeder von ihnen.</li><li><em>Profile</em> listet deine Authenticator-Apps mit dem Datum, an dem sie hinzugefügt und zuletzt verwendet wurden. <em>Remove</em> entfernt eine, zum Beispiel die eines verlorenen Telefons; das braucht ebenfalls eine Anmeldung innerhalb der letzten 5 Minuten und beendet deine anderen Sitzungen. Das lokale Systemadmin-Konto behält nach der Setup-Phase mindestens eine.</li><li>Hast du alle Geräte verloren, setzt deine Administration deine zweiten Faktoren zurück. Du meldest dich dann nur mit deinem Passwort an und richtest eine neue Authenticator-App ein.</li></ul><h2 id="sitzungen-und-abmelden" tabindex="-1">Sitzungen und Abmelden <a class="header-anchor" href="#sitzungen-und-abmelden" aria-label="Permalink to “Sitzungen und Abmelden”">​</a></h2><p>Wähle <em>Log out</em> in der Kopfzeile oder in deinem Profil. Eine Sitzung endet außerdem nach 30 Minuten ohne Aktivität und spätestens 12 Stunden nach der Anmeldung.</p>`,4)])}var l=n(s,[[`render`,c]]);export{o as __pageData,l as default};